insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('NZ:early-childhood-teacher','2026-08-11',null,39.66,82500,15,0,0,0,8,8,0,8,1,40,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 241111 Early Childhood (Pre-primary School) Teacher — registered.','shortage_note','Current Green List Tier 2 status is direct policy-demand evidence; 15/20.','visa_basis','Green List Tier 2 supports Work to Residence after the qualifying period when the Teaching Council registration/certification and other current requirements are met; 8/10.','salary_method','Midpoint of Tahatū current most-common Early Childhood Teacher annual pay range NZD 72,000-93,000; 8/10.','entry_basis','Teaching Council-approved ECE initial teacher education commonly requires about 3-4 years for direct undergraduate entry, with graduate-entry routes also available; 8/15.','entry_burden_basis','Teaching Council registration and a current practising certificate are required to officially teach; 1/5.'),'2026-08-11'),
('NZ:primary-school-teacher','2026-08-11',null,39.66,82500,20,0,0,0,8,8,0,10,1,47,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 241213 Primary School Teacher. Māori-medium and intermediate teacher codes are not rolled into this canonical primary profile.','shortage_note','Primary School Teacher 241213 is on current Green List Tier 1; 20/20.','visa_basis','Tier 1 Straight to Residence when Teaching Council registration, a provisional or full practising certificate and other Green List requirements are met; 10/10.','salary_method','Midpoint of Tahatū current most-common Primary School Teacher annual pay range NZD 72,000-93,000; 8/10.','entry_basis','Approved initial teacher education is required; direct bachelor and graduate-entry teaching routes are available; 8/15.','entry_burden_basis','Teaching Council registration and a current practising certificate are mandatory for official teaching; 1/5.'),'2026-08-11'),
('NZ:secondary-school-teacher','2026-08-11',null,39.66,82500,20,0,0,0,8,8,0,10,1,47,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 241411 Secondary School Teacher.','shortage_note','Secondary School Teacher 241411 is on current Green List Tier 1; 20/20.','visa_basis','Tier 1 Straight to Residence when Teaching Council registration, a provisional or full practising certificate and other current requirements are met; 10/10.','salary_method','Midpoint of Tahatū current most-common Secondary School Teacher annual pay range NZD 72,000-93,000; 8/10.','entry_basis','Teaching Council-approved secondary initial teacher education is required, often following or incorporating subject-degree study; 8/15.','entry_burden_basis','Teaching Council registration and a current practising certificate are mandatory for official teaching; 1/5.'),'2026-08-11'),
('NZ:special-education-teacher','2026-08-11',null,39.66,82500,15,0,0,0,8,8,0,8,1,40,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Roll-up of ANZSCO 241511 Special Needs Teacher, 241512 Teacher of the Hearing Impaired, 241513 Teacher of the Sight Impaired and 241599 Special Education Teachers nec. Teacher aides and learning-support assistants are excluded.','shortage_note','The four special-education teacher occupations are on current Green List Tier 2; 15/20.','visa_basis','Tier 2 Work to Residence when the registered-teacher and other current Green List requirements are satisfied; 8/10.','salary_method','No exact Tahatū Special Education Teacher pay page was used. Salary transparently uses the NZD 72,000-93,000 most-common range published for registered primary/secondary teachers as a representative teacher-pay proxy; 8/10.','entry_basis','A Teaching Council-approved ITE route and teacher registration are the professional foundation, with special-education expertise layered onto registered teaching; 8/15.','entry_burden_basis','Teaching Council registration and a current practising certificate are mandatory for the Green List teacher scope; 1/5.'),'2026-08-11'),
('NZ:social-worker','2026-08-11',null,46.63,97000,20,0,0,0,8,8,0,10,1,47,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 272511 Social Worker.','shortage_note','Social Worker 272511 is on current Green List Tier 1; 20/20.','visa_basis','Tier 1 Straight to Residence when SWRB registration and the listed qualification/current immigration requirements are met; 10/10.','salary_method','Midpoint of Tahatū current most-common Social Worker annual pay range NZD 87,000-107,000; 8/10.','entry_basis','A SWRB-recognised social-work qualification or accepted overseas/Australian qualification pathway is required. The former section 13 experience-only pathway closed to new applications on 28 February 2026; 8/15.','entry_burden_basis','SWRB registration and a current annual Practising Certificate are legally required to practise as a social worker; 1/5.'),'2026-08-11'),
('NZ:youth-worker','2026-08-11',null,32.69,68000,0,0,0,0,15,4,0,5,5,29,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 411716 Youth Worker.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned.','visa_basis','Standard skilled-work treatment when the specific role and applicant meet current immigration requirements; 5/10.','salary_method','Midpoint of Tahatū current most-common Youth Worker annual pay range NZD 63,000-73,000; 4/10.','entry_basis','Tahatū describes 0-3 years of training, with youth-work/community qualifications useful rather than one mandatory statutory degree; 15/15.','entry_burden_basis','Youth work is not a statutorily registered occupation; police vetting and employer safeguarding requirements may apply; 5/5.'),'2026-08-11'),
('NZ:community-worker','2026-08-11',null,26.50,55120,0,0,0,0,15,2,0,5,5,27,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','ANZSCO 411711 Community Worker. This community-development/support scope is distinct from Personal Care Assistant 423313 used by the Health Care Worker profile.','shortage_note','No current Green List or recurring occupation-specific shortage credit is assigned.','visa_basis','Standard skilled-work treatment when a specific community-worker role meets current classification and immigration requirements; 5/10.','salary_method','Tahatū does not provide a clean exact Community Worker pay page in the reviewed layer; midpoint of Support Worker most-common hourly pay NZD 25-28, annualised at 2,080 hours, is used as the closest transparent community-support proxy; 2/10.','entry_basis','Community/support work can be entered through on-the-job experience and certificate-level community or social-service study; 15/15.','entry_burden_basis','No statutory occupational registration applies to generic Community Worker 411711; 5/5.'),'2026-08-11'),
('NZ:counsellor','2026-08-11',null,46.63,97000,20,0,0,0,10,8,0,10,3,51,'career-opportunity-nz-v1','provisional',jsonb_build_object('classification_scope','Green List-aligned roll-up of ANZSCO 272111 Careers Counsellor, 272113 Family and Marriage Counsellor, 272114 Rehabilitation Counsellor, 272115 Student Counsellor and 272199 Counsellors nec. Drug and Alcohol Counsellor 272112 is excluded because the current Green List treats addiction practice under a separate DAPAANZ registration pathway.','shortage_note','The NZAC-membership counsellor group is on current Green List Tier 1; 20/20.','visa_basis','Tier 1 Straight to Residence when the applicable NZ Association of Counsellors membership and qualification requirements are met; 10/10.','salary_method','Midpoint of Tahatū current most-common Counsellor annual pay range NZD 87,000-107,000; 8/10.','entry_basis','Bachelor-level counselling or another listed professional degree plus the applicable NZAC-accredited pathway is common for Green List eligibility; 10/15.','entry_burden_basis','Counselling is not represented here as a universal statutory-register profession, but Green List access for this roll-up depends on NZAC membership and qualifying study; 3/5.'),'2026-08-11')
